26	/** @public */
27	export interface BgContextValue {
28	  bg: ContainerBg | undefined;
29	}
30	
31	/** @public */
32	export interface BgProviderProps {
33	  bg: ContainerBg;
34	  children: ReactNode;
35	}
36	
37	const BgContext = createVersionedContext<{
38	  1: BgContextValue;
39	}>('bg-context');
40	
41	/**
42	 * Increments a neutral bg level by one, capping at 'neutral-3'.
43	 * Intent backgrounds (danger, warning, success) pass through unchanged.
44	 *
45	 * The 'neutral-4' level is reserved for consumer component CSS and is
46	 * never set on providers.
47	 *
48	 * @internal
49	 */
50	function incrementNeutralBg(bg: ContainerBg | undefined): ContainerBg {
51	  if (!bg) return 'neutral-1';
52	  if (bg === 'neutral-1') return 'neutral-2';
53	  if (bg === 'neutral-2') return 'neutral-3';
54	  if (bg === 'neutral-3') return 'neutral-3'; // capped at neutral-3
55	  // Intent values pass through unchanged
56	  return bg;
57	}
58	
59	/**
60	 * Provider component that establishes the bg context for child components.
61	 *
62	 * @public
63	 */
64	export const BgProvider = ({ bg, children }: BgProviderProps) => {
65	  return (
66	    <BgContext.Provider value={createVersionedValueMap({ 1: { bg } })}>
67	      {children}
68	    </BgContext.Provider>
69	  );
70	};
71	
72	/**
73	 * Resets the bg context to undefined, cutting any inherited neutral chain.
74	 * Use this inside overlay components (Popover, Tooltip, Dialog, Menu) so
75	 * their content always starts from neutral-1 regardless of where the trigger
76	 * is placed in the tree.
77	 *
78	 * @internal
79	 */
80	export const BgReset = ({ children }: { children: ReactNode }) => {
81	  return (
82	    <BgContext.Provider
83	      value={createVersionedValueMap({ 1: { bg: undefined } })}
84	    >
85	      {children}
86	    </BgContext.Provider>
87	  );
88	};
89	
90	/**
91	 * Hook for consumer components (e.g. Button) to read the parent bg context.
92	 *
93	 * Returns the parent container's bg unchanged. The consumer component's CSS
94	 * handles the visual step-up (e.g. on a neutral-1 surface, the consumer
95	 * uses neutral-2 tokens via `data-on-bg`).
96	 *
97	 * @public
98	 */
99	export function useBgConsumer(): BgContextValue {
100	  const value = useContext(BgContext)?.atVersion(1);
101	  return value ?? { bg: undefined };
102	}
103	
104	/**
105	 * Hook for provider components (e.g. Box, Card) to resolve and provide bg context.
106	 *
107	 * **Resolution rules:**
108	 *
109	 * - `bg` is `undefined` -- transparent, no context change, returns `{ bg: undefined }`.
110	 *   This is the default for Box, Flex, and Grid (they do **not** auto-increment).
111	 * - `bg` is `'neutral'` -- when the parent bg is neutral, increments the neutral
112	 *   level from the parent context, capping at `neutral-3`. When the parent bg is
113	 *   an intent (`'danger'` | `'warning'` | `'success'`), the intent passes through
114	 *   unchanged (i.e. `bg: 'neutral'` does not override the parent intent). The
115	 *   increment is always relative to the parent; it is not possible to pin a
116	 *   container to an explicit neutral level.
117	 * - `bg` is `'danger'` | `'warning'` | `'success'` -- sets the bg to that intent
118	 *   explicitly, regardless of the parent value.
119	 *
120	 * **Capping:**
121	 *
122	 * Provider components cap at `neutral-3`. The `neutral-4` level is **not** a valid
123	 * prop value -- it exists only in consumer component CSS (e.g. a Button on a
124	 * `neutral-3` surface renders with `neutral-4` tokens via `data-on-bg`).
125	 *
126	 * The caller is responsible for wrapping children with `BgProvider` when the
127	 * resolved bg is defined.
128	 *
129	 * @public
130	 */
131	export function useBgProvider(bg?: Responsive<ProviderBg>): BgContextValue {
132	  const { breakpoint } = useBreakpoint();
133	  const context = useBgConsumer();
134	
135	  if (bg === undefined) {
136	    return { bg: undefined };
137	  }
138	
139	  const resolved = resolveResponsiveValue(bg, breakpoint);
140	
141	  if (resolved === 'neutral') {
142	    return { bg: incrementNeutralBg(context.bg) };
143	  }
144	
145	  return { bg: resolved };
146	}
