18	import {
19	  createVersionedContext,
20	  useVersionedContext,
21	} from '@backstage/version-bridge';
22	import type { AnalyticsTracker, UseAnalyticsFn } from './types';
23	
24	/** @internal */
25	export const noopTracker: AnalyticsTracker = {
26	  captureEvent: () => {},
27	};
28	
29	const noopUseAnalytics: UseAnalyticsFn = () => noopTracker;
30	
31	/** @internal */
32	export type BUIContextValue = {
33	  useAnalytics?: UseAnalyticsFn;
34	};
35	
36	/** @internal */
37	export const BUIContext = createVersionedContext<{
38	  1: BUIContextValue;
39	}>('bui');
40	
41	/**
42	 * Returns an AnalyticsTracker for capturing analytics events.
43	 *
44	 * By default returns a noop tracker. When a `BUIProvider` is present
45	 * in the tree, returns the tracker provided by the consumer's hook.
46	 *
47	 * @public
48	 */
49	export function useAnalytics(): AnalyticsTracker {
50	  const ctx = useVersionedContext<{ 1: BUIContextValue }>('bui')?.atVersion(1);
51	  const impl = ctx?.useAnalytics ?? noopUseAnalytics;
52	
53	  if (process.env.NODE_ENV !== 'production') {
54	    const prevImpl = useRef(impl);
55	    if (
56	      (prevImpl.current === noopUseAnalytics) !==
57	      (impl === noopUseAnalytics)
58	    ) {
59	      throw new Error(
60	        '@backstage/ui: The analytics hook changed between a noop and a real ' +
61	          'implementation. Ensure <BUIProvider> wraps all BUI components from first render.',
62	      );
63	    }
64	    prevImpl.current = impl;
65	  }
66	
67	  return impl();
68	}
