16	import { useMemo } from 'react';
17	import { useSyncExternalStore } from 'use-sync-external-store/shim';
18	import type { Breakpoint } from '../types';
19	
20	export const breakpoints: { name: string; id: Breakpoint; value: number }[] = [
21	  { name: 'Initial', id: 'initial', value: 0 },
22	  { name: 'Extra Small', id: 'xs', value: 640 },
23	  { name: 'Small', id: 'sm', value: 768 },
24	  { name: 'Medium', id: 'md', value: 1024 },
25	  { name: 'Large', id: 'lg', value: 1280 },
26	  { name: 'Extra Large', id: 'xl', value: 1536 },
27	];
28	
29	const breakpointIndex = new Map<Breakpoint, number>(
30	  breakpoints.map((bp, i) => [bp.id, i]),
31	);
32	
33	function bpIndex(key: Breakpoint): number {
34	  return breakpointIndex.get(key) ?? 0;
35	}
36	
37	const IS_SERVER =
38	  typeof window === 'undefined' || typeof window.matchMedia === 'undefined';
39	
40	function computeBreakpoint(): Breakpoint {
41	  if (IS_SERVER) {
42	    return 'initial';
43	  }
44	  for (let i = breakpoints.length - 1; i >= 0; i--) {
45	    if (window.matchMedia(`(min-width: ${breakpoints[i].value}px)`).matches) {
46	      return breakpoints[i].id;
47	    }
48	  }
49	  return 'initial';
50	}
51	
52	// --- Module-scoped singleton store ---
53	// This is intentionally not a global singleton. Multiple copies of this module
54	// (e.g. different package versions or module federation remotes) each get their
55	// own store. This avoids cross-version coupling at the cost of a few extra
56	// listeners, which is a fine trade-off.
57	// `current` is initialized lazily on first client-side access.
58	
59	let current: Breakpoint | undefined;
60	const listeners = new Set<() => void>();
61	let initialized = false;
62	
63	function ensureInitialized(): void {
64	  if (initialized || IS_SERVER) {
65	    return;
66	  }
67	  initialized = true;
68	  current = computeBreakpoint();
69	
70	  // Register one listener per breakpoint. When any query fires, re-evaluate
71	  // all breakpoints to find the new active one. Notify subscribers only if
72	  // the active breakpoint actually changed.
73	  for (const bp of breakpoints) {
74	    const mql = window.matchMedia(`(min-width: ${bp.value}px)`);
75	    mql.addEventListener('change', () => {
76	      const next = computeBreakpoint();
77	      if (next !== current) {
78	        current = next;
79	        for (const cb of listeners) {
80	          cb();
81	        }
82	      }
83	    });
84	  }
85	}
86	
87	function subscribe(callback: () => void): () => void {
88	  ensureInitialized();
89	  listeners.add(callback);
90	  return () => {
91	    listeners.delete(callback);
92	  };
93	}
94	
95	function getSnapshot(): Breakpoint {
96	  ensureInitialized();
97	  return current ?? 'initial';
98	}
99	
100	function getServerSnapshot(): Breakpoint {
101	  return 'initial';
102	}
103	
104	/** @public */
105	export const useBreakpoint = () => {
106	  const breakpoint = useSyncExternalStore(
107	    subscribe,
108	    getSnapshot,
109	    getServerSnapshot,
110	  );
111	
112	  return useMemo(
113	    () => ({
114	      breakpoint,
115	      up: (key: Breakpoint): boolean => bpIndex(breakpoint) >= bpIndex(key),
116	      down: (key: Breakpoint): boolean => bpIndex(breakpoint) < bpIndex(key),
117	    }),
118	    [breakpoint],
119	  );
120	};
