import {
  resolveResponsiveValue,
  resolveDefinitionProps,
  processUtilityProps,
} from './helpers';

describe('resolveResponsiveValue', () => {
  it('returns primitives and plain objects unchanged', () => {
    expect(resolveResponsiveValue('x', 'md')).toBe('x');
    expect(resolveResponsiveValue(5, 'md')).toBe(5);
    expect(resolveResponsiveValue(undefined, 'md')).toBeUndefined();
    expect(resolveResponsiveValue(null, 'md')).toBeNull();
    const initialOnly = { initial: 'a' };
    expect(resolveResponsiveValue(initialOnly, 'md')).toBe(initialOnly);
  });

  it('resolves at exact breakpoint with fallback', () => {
    expect(resolveResponsiveValue({ initial: '1', md: '4' }, 'md')).toBe('4');
    expect(resolveResponsiveValue({ initial: '1', md: '4' }, 'lg')).toBe('4');
    expect(resolveResponsiveValue({ initial: '1' }, 'md')).toBe('1');
    expect(resolveResponsiveValue({ md: 'x' }, 'initial')).toBe('x');
    expect(
      resolveResponsiveValue({ initial: undefined, sm: 's' }, 'initial'),
    ).toBe('s');
  });
});

const definition: any = {
  styles: { 'bui-Root': 'bui-Root' },
  classNames: { root: 'bui-Root' },
  propDefs: {
    as: { default: 'div' },
    variant: { dataAttribute: true },
    disabled: {},
    m: {},
  },
  utilityProps: ['m', 'p'],
};

describe('resolveDefinitionProps', () => {
  it('separates own and rest, applies defaults and preserves falsy', () => {
    const { ownPropsResolved, restProps } = resolveDefinitionProps(
      definition,
      { variant: 'x', disabled: false, p: '2', id: 'foo', m: '3' },
      'md',
    );
    expect(ownPropsResolved).toEqual({
      as: 'div',
      variant: 'x',
      disabled: false,
      m: '3',
    });
    expect(restProps).toEqual({ id: 'foo' });
    expect('as' in ownPropsResolved).toBe(true);
  });

  it('omits undefined-with-no-default', () => {
    const { ownPropsResolved } = resolveDefinitionProps(definition, {}, 'md');
    expect('variant' in ownPropsResolved).toBe(false);
    expect(ownPropsResolved.as).toBe('div');
  });
});

describe('processUtilityProps', () => {
  it('returns empty when no values', () => {
    expect(processUtilityProps({ m: undefined }, ['m'])).toEqual({
      utilityClasses: '',
      utilityStyle: {},
    });
  });

  it('discrete, custom, responsive, transforms', () => {
    expect(processUtilityProps({ m: '2' }, ['m']).utilityClasses).toBe(
      'bui-m-2',
    );
    expect(
      processUtilityProps({ position: 'relative' }, ['position'])
        .utilityClasses,
    ).toBe('bui-position-relative');
    // invalid fixed value ignored
    expect(
      processUtilityProps({ position: 'nope' }, ['position']),
    ).toEqual({ utilityClasses: '', utilityStyle: {} });
    // custom
    const w = processUtilityProps({ width: '100px' }, ['width']);
    expect(w.utilityClasses).toBe('bui-w');
    expect(w.utilityStyle).toEqual({ '--width': '100px' });
    // responsive
    expect(
      processUtilityProps({ m: { initial: '2', md: '4' } }, ['m'])
        .utilityClasses,
    ).toBe('bui-m-2 md:bui-m-4');
    // transforms
    expect(processUtilityProps({ grow: true }, ['grow']).utilityStyle).toEqual({
      '--grow': 1,
    });
    expect(processUtilityProps({ basis: 42 }, ['basis']).utilityStyle).toEqual({
      '--basis': '42px',
    });
  });
});
