import { ReactNode } from 'react';
import { renderHook } from '@testing-library/react';
import { MemoryRouter, Routes, Route } from 'react-router-dom';
import { resolveResponsiveValue } from './helpers';
import { useDefinition } from './useDefinition';
import { BgProvider } from '../useBg';
import { noopTracker } from '../../analytics/useAnalytics';

describe('resolveResponsiveValue spec edge cases', () => {
  it('handles fallback and initial-only', () => {
    expect(resolveResponsiveValue({ initial: '1', md: '4' }, 'lg')).toBe('4');
    expect(resolveResponsiveValue({ initial: '1' }, 'md')).toEqual({
      initial: '1',
    });
    expect(resolveResponsiveValue({ md: 'x' }, 'initial')).toBe('x');
    expect(
      resolveResponsiveValue({ initial: undefined, sm: 's' }, 'initial'),
    ).toBe('s');
  });
});

const bgProviderDef: any = {
  styles: { 'bui-Box': 'bui-Box' },
  classNames: { root: 'bui-Box' },
  bg: 'provider',
  propDefs: { bg: { dataAttribute: true }, children: {}, className: {} },
  utilityProps: ['m'],
};

const consumerDef: any = {
  styles: { 'bui-Btn': 'bui-Btn' },
  classNames: { root: 'bui-Btn' },
  bg: 'consumer',
  analytics: true,
  propDefs: { children: {}, className: {}, noTrack: {}, href: {} },
};

const plainDef: any = {
  styles: { 'bui-P': 'bui-P', 'bui-Icon': 'bui-Icon' },
  classNames: { root: 'bui-P', icon: 'bui-Icon' },
  propDefs: { children: {}, className: {} },
  utilityProps: ['m'],
};

describe('useDefinition', () => {
  it('classes target only root, non-target clean', () => {
    const { result } = renderHook(() =>
      useDefinition(plainDef, {
        className: 'user-cls',
        m: '2',
        children: 'hi',
      }),
    );
    expect(result.current.ownProps.classes.root).toContain('bui-P');
    expect(result.current.ownProps.classes.root).toContain('user-cls');
    expect(result.current.ownProps.classes.root).toContain('bui-m-2');
    expect(result.current.ownProps.classes.icon).not.toContain('user-cls');
    expect(result.current.ownProps.classes.icon).not.toContain('bui-m-2');
    expect(result.current.ownProps.children).toBe('hi');
    expect(result.current.ownProps.childrenWithBgProvider).toBeUndefined();
    expect('analytics' in result.current).toBe(false);
  });

  it('bg provider increments neutral and wraps children', () => {
    const wrapper = ({ children }: { children: ReactNode }) => (
      <BgProvider bg="neutral-1">{children}</BgProvider>
    );
    const { result } = renderHook(
      () => useDefinition(bgProviderDef, { bg: 'neutral', children: 'x' }),
      { wrapper },
    );
    expect(result.current.dataAttributes['data-bg']).toBe('neutral-2');
    expect(result.current.ownProps.childrenWithBgProvider).toBeDefined();
    expect('children' in result.current.ownProps).toBe(false);
  });

  it('bg provider undefined => raw children, no data-bg', () => {
    const { result } = renderHook(() =>
      useDefinition(bgProviderDef, { children: 'raw' }),
    );
    expect(result.current.dataAttributes['data-bg']).toBeUndefined();
    expect(result.current.ownProps.childrenWithBgProvider).toBe('raw');
  });

  it('bg consumer sets data-on-bg and analytics noopTracker with noTrack', () => {
    const wrapper = ({ children }: { children: ReactNode }) => (
      <BgProvider bg="neutral-2">{children}</BgProvider>
    );
    const { result } = renderHook(
      () =>
        useDefinition(consumerDef, { children: 'c', noTrack: true }),
      { wrapper },
    );
    expect(result.current.dataAttributes['data-on-bg']).toBe('neutral-2');
    expect(result.current.ownProps.children).toBe('c');
    expect('childrenWithBgProvider' in result.current.ownProps).toBe(false);
    expect((result.current as any).analytics).toBe(noopTracker);
  });

  it('analytics real tracker when noTrack falsy', () => {
    const { result } = renderHook(() =>
      useDefinition(consumerDef, { children: 'c' }),
    );
    expect((result.current as any).analytics).toBeDefined();
    expect(typeof (result.current as any).analytics.captureEvent).toBe(
      'function',
    );
  });

  it('href resolution in router: relative and external', () => {
    const relWrapper = ({ children }: { children: ReactNode }) => (
      <MemoryRouter initialEntries={['/catalog']}>
        <Routes>
          <Route path="/catalog" element={children} />
        </Routes>
      </MemoryRouter>
    );
    const { result: rel } = renderHook(
      () => useDefinition(consumerDef, { children: 'c', href: 'foo' }),
      { wrapper: relWrapper },
    );
    expect(rel.current.ownProps.href).toBe('/catalog/foo');

    const { result: ext } = renderHook(
      () =>
        useDefinition(consumerDef, {
          children: 'c',
          href: 'https://example.com',
        }),
      { wrapper: relWrapper },
    );
    expect(ext.current.ownProps.href).toBe('https://example.com');

    const { result: none } = renderHook(
      () => useDefinition(consumerDef, { children: 'c' }),
      { wrapper: relWrapper },
    );
    expect('href' in none.current.ownProps).toBe(false);
  });
});
